static const char *TAG = "web_server";

// Symbols generated by the build system for the EMBED_TXTFILES entry
// ("dashboard.html") declared in main/CMakeLists.txt.
extern const uint8_t dashboard_html_start[] asm("_binary_dashboard_html_start");
extern const uint8_t dashboard_html_end[]   asm("_binary_dashboard_html_end");

static httpd_handle_t s_server = NULL;

static bool require_auth(httpd_req_t *req, bool csrf) {
    if (auth_authorize(req, csrf)) return true;
    httpd_resp_send_err(req, HTTPD_401_UNAUTHORIZED, "Authentication required");
    return false;
}

// ----------------------------------------------------------------------------
// Small helpers
// ----------------------------------------------------------------------------

// Reads the full request body (expects application/x-www-form-urlencoded,
// small size) into `buf`, null-terminated. Returns body length, or -1 on error.
static int read_body(httpd_req_t *req, char *buf, size_t buf_size) {
    int total = 0;
    int remaining = req->content_len;
    if (remaining <= 0 || (size_t)remaining >= buf_size) {
        return -1;
    }
    while (remaining > 0) {
        int r = httpd_req_recv(req, buf + total, remaining);
        if (r <= 0) return -1;
        total += r;
        remaining -= r;
    }
    buf[total] = '\0';
    return total;
}

static bool copy_text(char *dst, size_t dst_size, const char *src) {
    size_t n = strnlen(src, dst_size);
    if (n >= dst_size) return false;
    memset(dst, 0, dst_size);
    memcpy(dst, src, n);
    return true;
}

// Escapes a string for safe embedding in a JSON string literal.
static void json_escape_append(char *dst, size_t dst_size, const char *src) {
    size_t len = strlen(dst);
    for (size_t i = 0; src[i] != '\0' && len < dst_size - 2; i++) {
        char c = src[i];
        if (c == '"' || c == '\\') {
            if (len < dst_size - 3) dst[len++] = '\\';
            else break;
        }
        dst[len++] = c;
    }
    dst[len] = '\0';
}

