static esp_err_t root_get_handler(httpd_req_t *req) {
    ESP_LOGI(TAG, "GET /");
    size_t html_len = dashboard_html_end - dashboard_html_start;
    httpd_resp_set_type(req, "text/html");
    httpd_resp_send(req, (const char *)dashboard_html_start, html_len);
    return ESP_OK;
}

static esp_err_t status_get_handler(httpd_req_t *req) {
    if (!require_auth(req, false)) return ESP_FAIL;
    int64_t uptime_us = esp_timer_get_time() - g_boot_time_us;
    uint32_t uptime_sec = (uint32_t)(uptime_us / 1000000);

    char ip_str[16];
    wifi_manager_get_ip_str(ip_str, sizeof(ip_str));

    char ssid_escaped[128] = "";
    json_escape_append(ssid_escaped, sizeof(ssid_escaped), g_net_cfg.ssid);

    char json[512];
    snprintf(json, sizeof(json),
        "{"
        "\"uptimeSec\":%u,"
        "\"freeHeap\":%u,"
        "\"freePsram\":%u,"
        "\"totalPsram\":%u,"
        "\"totalQueries\":%u,"
        "\"blockedQueries\":%u,"
        "\"blocklistCount\":%d,"
        "\"ip\":\"%s\","
        "\"ssid\":\"%s\","
        "\"wifiFailureReason\":%d,"
        "\"timeValid\":%s,"
        "\"utcOffsetMinutes\":%d"
        ",\"sessionRemainingSec\":%u"
        "}",
        (unsigned)uptime_sec,
        (unsigned)esp_get_free_heap_size(),
        (unsigned)heap_caps_get_free_size(MALLOC_CAP_SPIRAM),
        (unsigned)heap_caps_get_total_size(MALLOC_CAP_SPIRAM),
        (unsigned)g_total_queries,
        (unsigned)g_blocked_queries,
        blocklist_count(),
        ip_str,
        ssid_escaped, wifi_manager_get_last_disconnect_reason(), time_service_is_valid() ? "true" : "false", time_service_get_utc_offset_minutes(), (unsigned)auth_session_remaining_seconds()
    );

    httpd_resp_set_type(req, "application/json");
    httpd_resp_send(req, json, HTTPD_RESP_USE_STRLEN);
    return ESP_OK;
}

static esp_err_t blocklist_get_handler(httpd_req_t *req) {
    if (!require_auth(req, false)) return ESP_FAIL;
    char domains[MAX_BLOCKLIST][MAX_DOMAIN_LEN];
    int count = blocklist_get_all(domains, MAX_BLOCKLIST);

    // Worst case: 200 domains * (128 chars + quotes/comma) ~ 26KB; allocate
    // from heap dynamically rather than blowing the stack.
    size_t buf_size = (size_t)count * (MAX_DOMAIN_LEN + 4) + 8;
    char *json = malloc(buf_size);
    if (!json) {
        httpd_resp_send_500(req);
        return ESP_FAIL;
    }

    size_t pos = 0;
    json[pos++] = '[';
    for (int i = 0; i < count; i++) {
        if (i > 0) json[pos++] = ',';
        json[pos++] = '"';
        for (int j = 0; domains[i][j] != '\0'; j++) {
            char c = domains[i][j];
            if (c == '"' || c == '\\') json[pos++] = '\\';
            json[pos++] = c;
        }
        json[pos++] = '"';
    }
    json[pos++] = ']';
    json[pos] = '\0';

    httpd_resp_set_type(req, "application/json");
    httpd_resp_send(req, json, pos);
    free(json);
    return ESP_OK;
}

static esp_err_t blocklist_add_handler(httpd_req_t *req) {
    if (!require_auth(req, true)) return ESP_FAIL;
    char body[256];
    if (read_body(req, body, sizeof(body)) < 0) {
        httpd_resp_send_err(req, HTTPD_400_BAD_REQUEST, "Invalid body");
        return ESP_FAIL;
    }
    char domain[MAX_DOMAIN_LEN];
    if (httpd_query_key_value(body, "domain", domain, sizeof(domain)) != ESP_OK) {
        httpd_resp_send_err(req, HTTPD_400_BAD_REQUEST, "Missing 'domain' parameter");
        return ESP_FAIL;
    }

    ESP_LOGI(TAG, "POST /api/blocklist/add -> %s", domain);
    if (blocklist_add(domain)) {
        httpd_resp_send(req, "OK", HTTPD_RESP_USE_STRLEN);
    } else {
        httpd_resp_set_status(req, "409 Conflict");
        httpd_resp_send(req, "Duplicate or blocklist full", HTTPD_RESP_USE_STRLEN);
    }
    return ESP_OK;
}

static esp_err_t blocklist_remove_handler(httpd_req_t *req) {
    if (!require_auth(req, true)) return ESP_FAIL;
    char body[256];
    if (read_body(req, body, sizeof(body)) < 0) {
        httpd_resp_send_err(req, HTTPD_400_BAD_REQUEST, "Invalid body");
        return ESP_FAIL;
    }
    char domain[MAX_DOMAIN_LEN];
    if (httpd_query_key_value(body, "domain", domain, sizeof(domain)) != ESP_OK) {
        httpd_resp_send_err(req, HTTPD_400_BAD_REQUEST, "Missing 'domain' parameter");
        return ESP_FAIL;
    }

    ESP_LOGI(TAG, "POST /api/blocklist/remove -> %s", domain);
    if (blocklist_remove(domain)) {
        httpd_resp_send(req, "OK", HTTPD_RESP_USE_STRLEN);
    } else {
        httpd_resp_send_err(req, HTTPD_404_NOT_FOUND, "Domain not found");
    }
    return ESP_OK;
}

// Delayed reboot so the HTTP response reaches the client before esp_restart().
static void reboot_task(void *arg) {
    vTaskDelay(pdMS_TO_TICKS(1500));
    esp_restart();
}

static esp_err_t network_save_handler(httpd_req_t *req) {
    if (!require_auth(req, true)) return ESP_FAIL;
    char body[512];
    if (read_body(req, body, sizeof(body)) < 0) {
        httpd_resp_send_err(req, HTTPD_400_BAD_REQUEST, "Invalid body");
        return ESP_FAIL;
    }
    ESP_LOGI(TAG, "POST /api/network/save");

    char value[64];

    if (httpd_query_key_value(body, "ssid", value, sizeof(value)) == ESP_OK) {
        if (strlen(value) > 32 || !copy_text(g_net_cfg.ssid, sizeof(g_net_cfg.ssid), value)) { httpd_resp_send_err(req, HTTPD_400_BAD_REQUEST, "SSID too long"); return ESP_FAIL; }
    }
    if (httpd_query_key_value(body, "pass", value, sizeof(value)) == ESP_OK && strlen(value) > 0) {
        if (!copy_text(g_net_cfg.password, sizeof(g_net_cfg.password), value)) { httpd_resp_send_err(req, HTTPD_400_BAD_REQUEST, "Password too long"); return ESP_FAIL; }
    }

    bool has_ip = httpd_query_key_value(body, "ip", value, sizeof(value)) == ESP_OK && strlen(value) > 0;
    if (has_ip && !copy_text(g_net_cfg.local_ip, sizeof(g_net_cfg.local_ip), value)) { httpd_resp_send_err(req, HTTPD_400_BAD_REQUEST, "IP too long"); return ESP_FAIL; }

    bool has_gw = httpd_query_key_value(body, "gw", value, sizeof(value)) == ESP_OK && strlen(value) > 0;
    if (has_gw && !copy_text(g_net_cfg.gateway, sizeof(g_net_cfg.gateway), value)) { httpd_resp_send_err(req, HTTPD_400_BAD_REQUEST, "Gateway too long"); return ESP_FAIL; }

    bool has_sn = httpd_query_key_value(body, "sn", value, sizeof(value)) == ESP_OK && strlen(value) > 0;
    if (has_sn && !copy_text(g_net_cfg.subnet, sizeof(g_net_cfg.subnet), value)) { httpd_resp_send_err(req, HTTPD_400_BAD_REQUEST, "Subnet too long"); return ESP_FAIL; }

    g_net_cfg.use_static = has_ip && has_gw && has_sn;

    if (httpd_query_key_value(body, "tz", value, sizeof(value)) == ESP_OK) {
        char *end; long tz = strtol(value, &end, 10);
        if (*end || tz < -720 || tz > 840) { httpd_resp_send_err(req, HTTPD_400_BAD_REQUEST, "Invalid UTC offset"); return ESP_FAIL; }
        time_service_set_utc_offset_minutes((int)tz);
    }
    if (config_store_save() != ESP_OK) { httpd_resp_send_err(req, HTTPD_500_INTERNAL_SERVER_ERROR, "Could not save configuration"); return ESP_FAIL; }

    httpd_resp_send(req, "Saved. Rebooting...", HTTPD_RESP_USE_STRLEN);

    xTaskCreate(reboot_task, "reboot_task", 2048, NULL, 1, NULL);
    return ESP_OK;
}

static esp_err_t schedules_get_handler(httpd_req_t *req) {
    if (!require_auth(req, false)) return ESP_FAIL;
    site_schedule_t *entries = malloc(sizeof(site_schedule_t) * MAX_SCHEDULES);
    char *json = malloc(12288);
    if (!entries || !json) { free(entries); free(json); httpd_resp_send_500(req); return ESP_FAIL; }
    int count = schedule_store_get_all(entries, MAX_SCHEDULES); size_t p = 0;
    p += snprintf(json + p, 12288 - p, "[");
    for (int i = 0; i < count && p < 12288; ++i) p += snprintf(json + p, 12288 - p, "%s{\"domain\":\"%s\",\"start\":%u,\"end\":%u,\"enabled\":%s}", i ? "," : "", entries[i].domain, entries[i].start_minute, entries[i].end_minute, entries[i].enabled ? "true" : "false");
    snprintf(json + p, 12288 - p, "]"); httpd_resp_set_type(req, "application/json"); httpd_resp_sendstr(req, json);
    free(entries); free(json); return ESP_OK;
}
static esp_err_t profiles_get_handler(httpd_req_t *req) {
    if (!require_auth(req, false)) return ESP_FAIL;
    device_profile_t *profiles = malloc(sizeof(device_profile_t) * MAX_PROFILES); char *json = malloc(8192);
    if (!profiles || !json) { free(profiles); free(json); httpd_resp_send_500(req); return ESP_FAIL; }
    profile_store_get_all(profiles, MAX_PROFILES); size_t p = 0; p += snprintf(json + p, 8192-p, "[");
    for (int i=0;i<MAX_PROFILES;i++) if (profiles[i].used) { struct in_addr a = {.s_addr=profiles[i].ip_be}; char ip[16]; inet_ntop(AF_INET,&a,ip,sizeof(ip)); p += snprintf(json+p,8192-p,"%s{\"id\":%d,\"name\":\"%s\",\"ip\":\"%s\",\"total\":%u,\"blocked\":%u,\"alerts\":%u}",p>1?",":"",i,profiles[i].name,ip,(unsigned)profiles[i].total_queries,(unsigned)profiles[i].blocked_queries,profiles[i].alert_count); }
    snprintf(json+p,8192-p,"]"); httpd_resp_set_type(req,"application/json"); httpd_resp_sendstr(req,json); free(profiles); free(json); return ESP_OK;
}
static esp_err_t profile_add_handler(httpd_req_t *req) { if (!require_auth(req,true)) return ESP_FAIL; char body[160],name[PROFILE_NAME_LEN],ip[16]; if(read_body(req,body,sizeof(body))<0||httpd_query_key_value(body,"name",name,sizeof(name))!=ESP_OK||httpd_query_key_value(body,"ip",ip,sizeof(ip))!=ESP_OK||!profile_store_add(name,ip)){httpd_resp_send_err(req,HTTPD_400_BAD_REQUEST,"Invalid, duplicate, full, or unsaved profile");return ESP_FAIL;}httpd_resp_sendstr(req,"OK");return ESP_OK; }
static esp_err_t profile_remove_handler(httpd_req_t *req) { if (!require_auth(req,true)) return ESP_FAIL; char body[32],id[8]; if(read_body(req,body,sizeof(body))<0||httpd_query_key_value(body,"id",id,sizeof(id))!=ESP_OK||!profile_store_remove(atoi(id))){httpd_resp_send_err(req,HTTPD_400_BAD_REQUEST,"Profile not found");return ESP_FAIL;}httpd_resp_sendstr(req,"OK");return ESP_OK; }
static esp_err_t profile_block_add_handler(httpd_req_t *req) { if(!require_auth(req,true))return ESP_FAIL;char b[160],id[8],d[PROFILE_DOMAIN_LEN];if(read_body(req,b,sizeof(b))<0||httpd_query_key_value(b,"id",id,sizeof(id))!=ESP_OK||httpd_query_key_value(b,"domain",d,sizeof(d))!=ESP_OK||!profile_store_add_block(atoi(id),d)){httpd_resp_send_err(req,HTTPD_400_BAD_REQUEST,"Invalid device block");return ESP_FAIL;}httpd_resp_sendstr(req,"OK");return ESP_OK; }
static esp_err_t profile_schedule_add_handler(httpd_req_t *req) { if(!require_auth(req,true))return ESP_FAIL;char b[192],id[8],d[PROFILE_DOMAIN_LEN],v[8];if(read_body(req,b,sizeof(b))<0||httpd_query_key_value(b,"id",id,sizeof(id))!=ESP_OK||httpd_query_key_value(b,"domain",d,sizeof(d))!=ESP_OK||httpd_query_key_value(b,"start",v,sizeof(v))!=ESP_OK){httpd_resp_send_err(req,HTTPD_400_BAD_REQUEST,"Invalid device schedule");return ESP_FAIL;}int start=atoi(v);if(httpd_query_key_value(b,"end",v,sizeof(v))!=ESP_OK||!profile_store_add_schedule(atoi(id),d,start,atoi(v))){httpd_resp_send_err(req,HTTPD_400_BAD_REQUEST,"Invalid device schedule");return ESP_FAIL;}httpd_resp_sendstr(req,"OK");return ESP_OK; }
static esp_err_t schedule_add_handler(httpd_req_t *req) {
    if (!require_auth(req, true)) return ESP_FAIL;
    char body[320], domain[MAX_DOMAIN_LEN], value[16];
    if (read_body(req, body, sizeof(body)) < 0 || httpd_query_key_value(body, "domain", domain, sizeof(domain)) != ESP_OK || httpd_query_key_value(body, "start", value, sizeof(value)) != ESP_OK) { httpd_resp_send_err(req, HTTPD_400_BAD_REQUEST, "Invalid schedule"); return ESP_FAIL; }
    int start = atoi(value); if (httpd_query_key_value(body, "end", value, sizeof(value)) != ESP_OK) { httpd_resp_send_err(req, HTTPD_400_BAD_REQUEST, "Invalid schedule"); return ESP_FAIL; }
    if (!schedule_store_add(domain, start, atoi(value))) { httpd_resp_set_status(req, "409 Conflict"); httpd_resp_sendstr(req, "Invalid, duplicate, full, or unsaved schedule"); return ESP_FAIL; }
    httpd_resp_sendstr(req, "OK"); return ESP_OK;
}
static esp_err_t schedule_remove_handler(httpd_req_t *req) {
    if (!require_auth(req, true)) return ESP_FAIL;
    char body[192], domain[MAX_DOMAIN_LEN];
    if (read_body(req, body, sizeof(body)) < 0 || httpd_query_key_value(body, "domain", domain, sizeof(domain)) != ESP_OK || !schedule_store_remove(domain)) { httpd_resp_send_err(req, HTTPD_400_BAD_REQUEST, "Schedule not found"); return ESP_FAIL; } httpd_resp_sendstr(req, "OK"); return ESP_OK;
}
static esp_err_t schedule_enabled_handler(httpd_req_t *req) {
    if (!require_auth(req, true)) return ESP_FAIL;
    char body[192], domain[MAX_DOMAIN_LEN], value[8];
    if (read_body(req, body, sizeof(body)) < 0 || httpd_query_key_value(body, "domain", domain, sizeof(domain)) != ESP_OK || httpd_query_key_value(body, "enabled", value, sizeof(value)) != ESP_OK || (strcmp(value, "0") && strcmp(value, "1")) || !schedule_store_set_enabled(domain, value[0] == '1')) { httpd_resp_send_err(req, HTTPD_400_BAD_REQUEST, "Invalid schedule state"); return ESP_FAIL; } httpd_resp_sendstr(req, "OK"); return ESP_OK;
}
static esp_err_t auth_status_handler(httpd_req_t *req) {
    char session[33] = {0}; char cookie[160] = {0}; httpd_req_get_hdr_value_str(req, "Cookie", cookie, sizeof(cookie)); const char *p = strstr(cookie, "NGSID="); if (p) { p += 6; if (strcspn(p, "; ") == 32) { memcpy(session, p, 32); session[32] = '\0'; } }
    const char *csrf = auth_session_csrf(session); char json[96]; snprintf(json, sizeof(json), "{\"configured\":%s,\"authenticated\":%s,\"csrf\":\"%s\"}", auth_is_configured() ? "true" : "false", csrf ? "true" : "false", csrf ? csrf : ""); httpd_resp_set_type(req, "application/json"); httpd_resp_sendstr(req, json); return ESP_OK;
}
static esp_err_t auth_setup_handler(httpd_req_t *req) { char body[128], pass[64]; if (auth_is_configured() || read_body(req, body, sizeof(body)) < 0 || httpd_query_key_value(body, "password", pass, sizeof(pass)) != ESP_OK || auth_set_password(pass) != ESP_OK) { httpd_resp_send_err(req, HTTPD_400_BAD_REQUEST, "Password must be 12-63 characters"); return ESP_FAIL; } httpd_resp_sendstr(req, "OK"); return ESP_OK; }
static esp_err_t auth_login_handler(httpd_req_t *req) { char body[128], pass[64], session[33], csrf[33], cookie[128]; if (read_body(req, body, sizeof(body)) < 0 || httpd_query_key_value(body, "password", pass, sizeof(pass)) != ESP_OK || !auth_login(pass, session, csrf)) { httpd_resp_send_err(req, HTTPD_401_UNAUTHORIZED, "Invalid credentials"); return ESP_FAIL; } snprintf(cookie, sizeof(cookie), "NGSID=%s; Max-Age=43200; HttpOnly; SameSite=Strict; Path=/", session); httpd_resp_set_hdr(req, "Set-Cookie", cookie); httpd_resp_set_type(req, "application/json"); char json[64]; snprintf(json, sizeof(json), "{\"csrf\":\"%s\"}", csrf); httpd_resp_sendstr(req, json); return ESP_OK; }
static esp_err_t auth_logout_handler(httpd_req_t *req) { if (!require_auth(req, true)) return ESP_FAIL; char cookie[160] = {0}; httpd_req_get_hdr_value_str(req, "Cookie", cookie, sizeof(cookie)); char *p = strstr(cookie, "NGSID="); if (p) { p += 6; char session[33] = {0}; memcpy(session, p, 32); auth_logout(session); } httpd_resp_set_hdr(req, "Set-Cookie", "NGSID=; Max-Age=0; Path=/"); httpd_resp_sendstr(req, "OK"); return ESP_OK; }

// ----------------------------------------------------------------------------
// Server startup
// ----------------------------------------------------------------------------

void web_server_start(void) {
    httpd_config_t config = HTTPD_DEFAULT_CONFIG();
    config.core_id = 1;              // keep the HTTP server off the DNS engine's core
    config.stack_size = 8192;
    config.max_uri_handlers = 24;
    config.lru_purge_enable = true;

    if (httpd_start(&s_server, &config) != ESP_OK) {
        ESP_LOGE(TAG, "Failed to start HTTP server");
        return;
    }

    static const httpd_uri_t routes[] = {
        { .uri = "/",                       .method = HTTP_GET,  .handler = root_get_handler },
        { .uri = "/api/status",             .method = HTTP_GET,  .handler = status_get_handler },
        { .uri = "/api/blocklist",           .method = HTTP_GET,  .handler = blocklist_get_handler },
        { .uri = "/api/blocklist/add",       .method = HTTP_POST, .handler = blocklist_add_handler },
        { .uri = "/api/blocklist/remove",    .method = HTTP_POST, .handler = blocklist_remove_handler },
        { .uri = "/api/network/save",        .method = HTTP_POST, .handler = network_save_handler },
        { .uri = "/api/schedules",           .method = HTTP_GET,  .handler = schedules_get_handler },
        { .uri = "/api/schedules/add",       .method = HTTP_POST, .handler = schedule_add_handler },
        { .uri = "/api/schedules/remove",    .method = HTTP_POST, .handler = schedule_remove_handler },
        { .uri = "/api/schedules/enabled",   .method = HTTP_POST, .handler = schedule_enabled_handler },
        { .uri = "/api/profiles",             .method = HTTP_GET,  .handler = profiles_get_handler },
        { .uri = "/api/profiles/add",         .method = HTTP_POST, .handler = profile_add_handler },
        { .uri = "/api/profiles/remove",      .method = HTTP_POST, .handler = profile_remove_handler },
        { .uri = "/api/profiles/block/add",   .method = HTTP_POST, .handler = profile_block_add_handler },
        { .uri = "/api/profiles/schedule/add",.method = HTTP_POST, .handler = profile_schedule_add_handler },
        { .uri = "/api/auth/status",         .method = HTTP_GET,  .handler = auth_status_handler },
        { .uri = "/api/auth/setup",          .method = HTTP_POST, .handler = auth_setup_handler },
        { .uri = "/api/auth/login",          .method = HTTP_POST, .handler = auth_login_handler },
        { .uri = "/api/auth/logout",         .method = HTTP_POST, .handler = auth_logout_handler },
    };

    for (size_t i = 0; i < sizeof(routes) / sizeof(routes[0]); i++) {
        httpd_register_uri_handler(s_server, &routes[i]);
    }

    ESP_LOGI(TAG, "HTTP server started on port %d (core %d)", config.server_port, config.core_id);
}
